def get_block(grid, br, bc):
    r0, c0 = br * 3, bc * 3
    return [grid[r][c0:c0+3] for r in range(r0, r0+3)]

def block_feature(block):
    """
    Returns a signature:
    - 'mono_4' if all non-0 cells are 4
    - 'mono_6' if all non-0 cells are 6  
    - 'mono_X' if all non-0 cells are X
    - 'mixed' if multiple different non-bg colors
    - 'empty' if all cells are 0 or 5
    """
    non_bg = [x for row in block for x in row if x not in [0, 5]]
    if not non_bg:
        return 'empty'
    if len(set(non_bg)) == 1:
        return f'mono_{non_bg[0]}'
    return 'mixed'

